"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Trash2, GripVertical } from "lucide-react";
import { deleteScrumTask } from "@/app/actions/scrum-actions";

export default function TaskItem({ id, text, columnId }: { id: string, text: string, columnId: string }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id, data: { column: columnId } });

  const style = {
    transform: CSS.Translate.toString(transform),
    transition,
    opacity: isDragging ? 0.3 : 1,
  };

  return (
    <div ref={setNodeRef} style={style} className="group relative bg-[#070B24]/90 border border-teal-500/10 p-5 rounded-[1.5rem] hover:border-fuchsia-500/50 transition-all shadow-xl">
      <div className="flex items-start gap-4">
        <div {...attributes} {...listeners} className="mt-1 cursor-grab active:cursor-grabbing text-teal-500/20 hover:text-fuchsia-500 transition-colors">
          <GripVertical size={16} />
        </div>
        <div className="flex-1">
          <p className="text-xs text-teal-50 font-bold leading-relaxed tracking-wide uppercase">{text}</p>
          <div className="mt-4 flex justify-end opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={() => deleteScrumTask(id)} className="p-2 text-white/5 hover:text-red-500 transition-colors">
              <Trash2 size={14} />
            </button>
          </div>
        </div>
      </div>
      <div className="absolute left-0 top-6 bottom-6 w-1 bg-fuchsia-600 rounded-r-full shadow-[0_0_15px_#d946ef]" />
    </div>
  );
}