"use client";

import { useState } from "react";
import { DndContext, closestCorners, DragOverlay, DragStartEvent, DragOverEvent, DragEndEvent, PointerSensor, useSensor, useSensors } from "@dnd-kit/core";
import { ScrumTask, ColumnId, BoardState } from "src/types/scrum";
import { updateTaskStatus } from "@/app/actions/scrum-actions";
import ScrumColumn from "./ScrumColumn";
import TaskItem from "./TaskItem";

const COLUMNS: { id: ColumnId; title: string }[] = [
  { id: "backlog", title: "📋 Backlog" },
  { id: "sprint", title: "🎯 Sprint" },
  { id: "todo", title: "🟡 To Do" },
  { id: "progress", title: "🔵 In Progress" },
  { id: "done", title: "✅ Done" },
];

export default function ScrumBoard({ initialTasks }: { initialTasks: ScrumTask[] }) {
  const [items, setItems] = useState<BoardState>(() => {
    const board: BoardState = { backlog: [], sprint: [], todo: [], progress: [], done: [] };
    initialTasks.forEach(task => { if (board[task.columnId]) board[task.columnId].push(task); });
    return board;
  });
  const [activeTask, setActiveTask] = useState<ScrumTask | null>(null);
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  const handleDragStart = (event: DragStartEvent) => {
    const task = Object.values(items).flat().find(i => i.id === event.active.id);
    if (task) setActiveTask(task);
  };

  const handleDragOver = (event: DragOverEvent) => {
    const { active, over } = event;
    if (!over) return;
    const activeCol = active.data.current?.column as ColumnId;
    const overCol = (over.data.current?.column || over.id) as ColumnId;
    if (!activeCol || !overCol || activeCol === overCol) return;

    setItems((prev) => {
      const activeItems = prev[activeCol];
      const overItems = prev[overCol] || [];
      const task = activeItems.find(i => i.id === active.id);
      if (!task) return prev;
      return {
        ...prev,
        [activeCol]: activeItems.filter(i => i.id !== active.id),
        [overCol]: [...overItems, { ...task, columnId: overCol }],
      };
    });
  };

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (over) {
      const overCol = (over.data.current?.column || over.id) as ColumnId;
      await updateTaskStatus(active.id as string, overCol);
    }
    setActiveTask(null);
  };

  return (
    <DndContext sensors={sensors} collisionDetection={closestCorners} onDragStart={handleDragStart} onDragOver={handleDragOver} onDragEnd={handleDragEnd}>
      <div className="flex gap-6 p-4 overflow-x-auto min-h-[70vh] custom-scrollbar">
        {COLUMNS.map((col) => (
          <ScrumColumn key={col.id} id={col.id} title={col.title} tasks={items[col.id]} />
        ))}
      </div>
      <DragOverlay>
        {activeTask && (
          <div className="opacity-80 rotate-2 scale-105">
            <TaskItem id={activeTask.id} text={activeTask.content} columnId={activeTask.columnId} />
          </div>
        )}
      </DragOverlay>
    </DndContext>
  );
}