"use server";

import { prisma } from "src/lib/prisma"; 
import { revalidatePath } from "next/cache";
import { ColumnId } from "src/types/scrum";

export async function createScrumTask(content: string, columnId: ColumnId) {
  await prisma.task.create({
    data: {
      title: content,
      description: JSON.stringify({ columnId }),
      // userId: "user_id_buraya", // Auth eklediğinde burayı açarsın
    },
  });
  revalidatePath("/scrumboard");
}

export async function updateTaskStatus(taskId: string, newColumnId: ColumnId) {
  const task = await prisma.task.findUnique({ where: { id: taskId } });
  if (!task) return;

  const currentDesc = JSON.parse(task.description || "{}");
  await prisma.task.update({
    where: { id: taskId },
    data: {
      description: JSON.stringify({ ...currentDesc, columnId: newColumnId }),
    },
  });
  revalidatePath("/scrumboard");
}

export async function deleteScrumTask(taskId: string) {
  await prisma.task.delete({ where: { id: taskId } });
  revalidatePath("/scrumboard");
}