"use client";

import { useDroppable } from "@dnd-kit/core";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { Plus } from "lucide-react";
import { useState } from "react";
import { ScrumTask, ColumnId } from "src/types/scrum";
import { createScrumTask } from "@/app/actions/scrum-actions";
import TaskItem from "./TaskItem";

export default function ScrumColumn({ id, title, tasks }: { id: ColumnId, title: string, tasks: ScrumTask[] }) {
  const { setNodeRef } = useDroppable({ id });
  const [showAdd, setShowAdd] = useState(false);
  const [input, setInput] = useState("");

  const handleAdd = async () => {
    if (!input.trim()) return;
    await createScrumTask(input, id);
    setInput("");
    setShowAdd(false);
  };

  return (
    <div className="flex flex-col w-80 shrink-0">
      <div className="flex items-center justify-between mb-4 px-2">
        <h2 className="text-[10px] font-black uppercase italic text-teal-500 tracking-[0.2em]">{title}</h2>
        <span className="text-[9px] bg-teal-500/10 px-2 py-0.5 rounded text-teal-500 font-mono border border-teal-500/20">{tasks.length}</span>
      </div>

      <div ref={setNodeRef} className="flex-1 bg-[#0E153A]/40 backdrop-blur-xl border border-teal-500/10 rounded-[2rem] p-4 min-h-[550px] shadow-2xl transition-all hover:border-teal-500/20">
        <SortableContext items={tasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
          <div className="flex flex-col gap-3">
            {tasks.map((task) => (
              <TaskItem key={task.id} id={task.id} text={task.content} columnId={id} />
            ))}
          </div>
        </SortableContext>

        <button onClick={() => setShowAdd(true)} className="w-full mt-6 py-4 border border-dashed border-teal-500/10 rounded-2xl text-teal-500/20 hover:text-fuchsia-400 hover:border-fuchsia-500/40 transition-all flex items-center justify-center gap-2 text-[10px] font-black tracking-widest">
          <Plus size={14} /> TAAK TOEVOEGEN
        </button>
      </div>

      {showAdd && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 backdrop-blur-md bg-black/40 animate-in fade-in duration-300">
          <div className="absolute inset-0" onClick={() => setShowAdd(false)} />
          <div className="relative bg-[#0E153A] border border-teal-500/30 p-10 rounded-[3rem] w-full max-w-md shadow-[0_0_50px_rgba(0,0,0,0.5)]">
            <h3 className="text-2xl font-black text-white italic mb-6 uppercase tracking-tighter">Nieuwe Taak</h3>
            <textarea className="w-full bg-[#070B24] border border-teal-500/20 rounded-2xl p-5 text-white focus:border-fuchsia-500 outline-none min-h-[150px] transition-all" placeholder="Wat is de missie?..." value={input} onChange={(e) => setInput(e.target.value)} autoFocus />
            <div className="flex justify-end gap-4 mt-8">
              <button onClick={() => setShowAdd(false)} className="text-[10px] font-black text-white/30 hover:text-white tracking-widest">ANNULEREN</button>
              <button onClick={handleAdd} className="px-8 py-3 bg-fuchsia-600 hover:bg-fuchsia-500 text-white rounded-xl font-black text-[10px] tracking-widest skew-x-[-12deg] transition-all">TOEVOEGEN</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}